STEP_COUNT = 1500

with DAG(
    dag_id="forgeai_bulk_5mb_dag",
    default_args=default_args,
    description="Auto-generated bulk DAG (~5MB) for sizing / parse-load tests",
    start_date=datetime(2026, 1, 1, tzinfo=timezone.utc),
    schedule=None,
    catchup=False,
    max_active_runs=1,
    dagrun_timeout=timedelta(minutes=60),
    tags=["poc", "forgeai", "bulk", "generated", "5MB"],
) as dag:
    previous_load = None
    for i in range(STEP_COUNT):
        extract = PythonOperator(
            task_id=f"step_{i}_extract",
            python_callable=globals()[f"step_{i}_extract"],
        )
        transform = PythonOperator(
            task_id=f"step_{i}_transform",
            python_callable=globals()[f"step_{i}_transform"],
        )
        load = PythonOperator(
            task_id=f"step_{i}_load",
            python_callable=globals()[f"step_{i}_load"],
        )
        extract >> transform >> load
        if previous_load is not None:
            previous_load >> extract
        previous_load = load
